int maxSubArray(vector<int>& a) {
    int cur = a[0], best = a[0];
    for (size_t j = 1; j < a.size(); ++j) {
        cur = max(a[j], cur + a[j]);
        best = max(best, cur);
    }
    return best;
}

public int maxSubArray(int[] a) {
    int cur = a[0], best = a[0];
    for (int j = 1; j < a.length; j++) {
        cur = Math.max(a[j], cur + a[j]);
        best = Math.max(best, cur);
    }
    return best;
}
